CREATE TYPE public.app_role AS ENUM ('administrador','chefe','operador','consulta');
CREATE TABLE public.units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 120), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.units TO authenticated; GRANT ALL ON public.units TO service_role;
ALTER TABLE public.units ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', unit_id uuid REFERENCES public.units(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES public.units(id), role public.app_role NOT NULL, UNIQUE(user_id,unit_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_unit() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT unit_id FROM public.profiles WHERE id=auth.uid() $$;
CREATE FUNCTION public.has_unit_role(roles public.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND unit_id=public.my_unit() AND role=ANY(roles)) $$;
REVOKE ALL ON FUNCTION public.my_unit(), public.has_unit_role(public.app_role[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_unit(), public.has_unit_role(public.app_role[]) TO authenticated;
CREATE POLICY units_read ON public.units FOR SELECT TO authenticated USING(id=public.my_unit());
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR unit_id=public.my_unit());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(unit_id=public.my_unit());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,email) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),120),coalesce(NEW.email,'')); RETURN NEW; END $$;
CREATE TRIGGER create_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.document_types (code text PRIMARY KEY, name text NOT NULL);
GRANT SELECT ON public.document_types TO authenticated; GRANT ALL ON public.document_types TO service_role;
ALTER TABLE public.document_types ENABLE ROW LEVEL SECURITY; CREATE POLICY types_read ON public.document_types FOR SELECT TO authenticated USING(true);
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), type_code text NOT NULL REFERENCES public.document_types(code), control_number text NOT NULL CHECK(length(trim(control_number)) BETWEEN 1 AND 80), origin_number text NOT NULL DEFAULT '', subject text NOT NULL CHECK(length(trim(subject)) BETWEEN 3 AND 500), received_date date NOT NULL DEFAULT current_date, due_date date, responsible_id uuid REFERENCES public.profiles(id), origin_sector text NOT NULL DEFAULT '', destination_sector text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','em_andamento','concluido')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('normal','alta','urgente')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), completed_date date, created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(unit_id,control_number));
GRANT SELECT,INSERT,UPDATE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.documents FOR SELECT TO authenticated USING(unit_id=public.my_unit());
CREATE POLICY documents_insert ON public.documents FOR INSERT TO authenticated WITH CHECK(unit_id=public.my_unit() AND created_by=auth.uid() AND public.has_unit_role(ARRAY['administrador','chefe','operador']::public.app_role[]));
CREATE POLICY documents_update ON public.documents FOR UPDATE TO authenticated USING(unit_id=public.my_unit() AND public.has_unit_role(ARRAY['administrador','chefe','operador']::public.app_role[])) WITH CHECK(unit_id=public.my_unit());
CREATE INDEX documents_unit_due ON public.documents(unit_id,due_date);
CREATE TABLE public.document_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), document_id uuid NOT NULL REFERENCES public.documents(id), actor_id uuid REFERENCES public.profiles(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.document_movements TO authenticated; GRANT ALL ON public.document_movements TO service_role; ALTER TABLE public.document_movements ENABLE ROW LEVEL SECURITY; CREATE POLICY movements_read ON public.document_movements FOR SELECT TO authenticated USING(unit_id=public.my_unit());
CREATE TABLE public.deadlines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), document_id uuid NOT NULL REFERENCES public.documents(id), title text NOT NULL, due_date date NOT NULL, UNIQUE(document_id));
GRANT SELECT ON public.deadlines TO authenticated; GRANT ALL ON public.deadlines TO service_role; ALTER TABLE public.deadlines ENABLE ROW LEVEL SECURITY; CREATE POLICY deadlines_read ON public.deadlines FOR SELECT TO authenticated USING(unit_id=public.my_unit());
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), document_id uuid REFERENCES public.documents(id), assignee_id uuid REFERENCES public.profiles(id), title text NOT NULL, due_date date, completed boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role; ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY; CREATE POLICY tasks_read ON public.tasks FOR SELECT TO authenticated USING(unit_id=public.my_unit());
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), user_id uuid NOT NULL REFERENCES public.profiles(id), message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(unit_id=public.my_unit() AND user_id=auth.uid());
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.units(id), actor_id uuid REFERENCES public.profiles(id), document_id uuid REFERENCES public.documents(id), action text NOT NULL, old_data jsonb, new_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(unit_id=public.my_unit() AND public.has_unit_role(ARRAY['administrador','chefe']::public.app_role[]));
CREATE FUNCTION public.validate_document() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.unit_id<>OLD.unit_id OR NEW.created_by<>OLD.created_by) THEN RAISE EXCEPTION 'Não é permitido transferir unidade ou autor'; END IF; IF NEW.responsible_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.responsible_id AND unit_id=NEW.unit_id) THEN RAISE EXCEPTION 'Responsável deve pertencer à unidade'; END IF; IF NEW.due_date<NEW.received_date THEN RAISE EXCEPTION 'Prazo anterior ao recebimento'; END IF; IF NEW.status='concluido' THEN NEW.completed_date=coalesce(NEW.completed_date,current_date); ELSE NEW.completed_date=NULL; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_document BEFORE INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.validate_document();
CREATE FUNCTION public.record_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(unit_id,actor_id,document_id,action,old_data,new_data) VALUES(NEW.unit_id,auth.uid(),NEW.id,TG_OP,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); INSERT INTO public.document_movements(unit_id,document_id,actor_id,action) VALUES(NEW.unit_id,NEW.id,auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'Documento cadastrado' ELSE 'Documento atualizado' END); IF NEW.due_date IS NOT NULL THEN INSERT INTO public.deadlines(unit_id,document_id,title,due_date) VALUES(NEW.unit_id,NEW.id,NEW.subject,NEW.due_date) ON CONFLICT(document_id) DO UPDATE SET title=EXCLUDED.title,due_date=EXCLUDED.due_date; ELSE DELETE FROM public.deadlines WHERE document_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER record_document AFTER INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.record_document();
CREATE FUNCTION public.initialize_unit(unit_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF public.my_unit() IS NOT NULL THEN RAISE EXCEPTION 'Conta já vinculada'; END IF; INSERT INTO public.units(name) VALUES(trim(unit_name)) RETURNING id INTO uid; UPDATE public.profiles SET unit_id=uid WHERE id=auth.uid(); INSERT INTO public.user_roles(user_id,unit_id,role) VALUES(auth.uid(),uid,'administrador'); RETURN uid; END $$;
REVOKE ALL ON FUNCTION public.initialize_unit(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.initialize_unit(text) TO authenticated;
CREATE FUNCTION public.assign_member(member_email text,member_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; target_unit uuid; BEGIN IF NOT public.has_unit_role(ARRAY['administrador']::public.app_role[]) THEN RAISE EXCEPTION 'Somente administrador'; END IF; SELECT id,unit_id INTO target,target_unit FROM public.profiles WHERE lower(email)=lower(trim(member_email)) FOR UPDATE; IF target IS NULL THEN RAISE EXCEPTION 'Conta não encontrada. O usuário precisa criar sua conta primeiro.'; END IF; IF target=auth.uid() THEN RAISE EXCEPTION 'Não altere sua própria permissão'; END IF; IF target_unit IS NOT NULL AND target_unit<>public.my_unit() THEN RAISE EXCEPTION 'Conta já vinculada a outra unidade'; END IF; UPDATE public.profiles SET unit_id=public.my_unit() WHERE id=target; INSERT INTO public.user_roles(user_id,unit_id,role) VALUES(target,public.my_unit(),member_role) ON CONFLICT(user_id,unit_id) DO UPDATE SET role=EXCLUDED.role; END $$;
REVOKE ALL ON FUNCTION public.assign_member(text,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assign_member(text,public.app_role) TO authenticated;